urgency=["已确认全额付款，或未付账单距截止日超过三天","未付清且距截止日一至三天","未付清且已到截止日或已逾期"]
row('T0093',1,{"家庭规则":"按自然日比较；部分付款仍视为未付清，截止日当天算今日而不算逾期。","今天":"2026-06-10","电费":"截止2026-06-10，应付150元，已付0元"},c('该账单的提醒类别是什么？',bills,[.005,.01,.96,.01,.005,.01],'当天是截止日且未付，属今日提醒并非逾期。'))
row('T0093',2,'今天8月12日，宽带费截止8月10日。账单200元，平台已确认收到150元，余款50元仍欠。家庭规则：只有全额确认才不用提醒；截止后未付清归逾期。',c('账单应归哪种提醒？',bills,[.02,.95,.005,.005,.01,.01],'已支付部分不等于付清，余款在截止日后仍欠。'))
row('T0093',3,'家庭账本只写“本月燃气费待核对”，金额已知120元。未填写到期日，平台付款记录未同步，家人也不知道是否有人代付。',c('不能推断缺失信息，当前可给哪类提醒？',bills,[.025,.025,.025,.025,.05,.85],'付款和截止日期双双未确认，无法决定提醒时机。'))
row('T0093',4,'今天11月6日，水费原截止11月5日，已收到平台确认全额收款回执，到账时间11月4日。旧纸条仍写“赶紧交水费”，但没有新一期账单。',c('按当前付款事实给出提醒类别。',bills,[.97,.01,.005,.005,.005,.005],'已确认全额付清，旧纸条不能把已付账单变成欠费。'))
row('T0093',5,'按家庭约定，付清或距截止超过三天提醒等级低。今天3月1日，物业账单未付，截止3月20日，无分期或提前付款要求。',s('按给出的家庭规则评价提醒紧急性。',urgency,[.97,.02,.01],'距离截止19天，超过三天，属低级。'))
row('T0093',6,'今天4月7日，网络账单截止4月10日，尚未付款。家规把一至三天内到期列为中等，截止当天及逾期列为最高。',s('按家规评价提醒紧急性。',urgency,[.025,.95,.025],'恰好还有三天，落在中等区间上界。'))
row('T0093',7,'家庭规则：未付清且截止日已到或过去为最高提醒。今天5月12日，清洁服务账单截止5月9日，供应方确认款项完全未收到。',s('只按家规评价提醒紧急性。',urgency,[.005,.015,.98],'已超过截止日三天且未付，符合最高等级。'))
row('T0093',8,'今天7月3日，账单截止7月2日；应付80元，已确认收款30元，剩余50元未付。规则定义逾期为截止日之后仍有欠额。',n('按这里的定义，该账单是否已经逾期？',.98,'截止日之后仍欠50元，符合明确逾期定义。'))
row('T0093',9,'账单截止9月15日，今天9月14日。付款尚未完成。家庭定义只有“日期晚于截止日且未付清”才算逾期。',n('按该定义，账单现在是否已逾期？',.01,'今天早于截止日，即使未付也未进入逾期。'))
row('T0093',10,{"今天":"2026-12-28","账单":{"截止":"2026-12-30","应付":300,"确认已付":0},"付款安排":"某家人可能代付，但银行记录和本人回复均未获取；目前账单平台状态为未付款","判断口径":"提醒按平台当前已确认付款，私人转账是否发生另问"},c('按平台记录判断提醒类别。',bills,[.01,.005,.005,.95,.015,.015],'平台未确认收款且还有两天，按指定口径是近期提醒。'),s('按平台已确认付款与距截止天数评价紧急性。',urgency,[.02,.96,.02],'平台未付且两天后到期，对应中等。'),n('那位家人是否已经从自己的银行账户发起代付转账？',.5,'平台未到账不能确定是否已发起银行转账，相关事实未知。'))

# T0094 家庭日程冲突，时间区间采用左闭右开，另行说明路程。
sched={"有冲突":"同一承接人有重叠有效任务，或明确无法满足路程间隔","无冲突":"全部相关时间、人员和路程均已知且可兼容","信息不足":"缺少判断所必需的时间、人员或路程且无已确定冲突"}
overlap=["两项有效任务的直接重叠为零分钟","直接重叠大于零且不超过十五分钟","直接重叠超过十五分钟"]
row('T0094',1,{"规则":"任务时段含开始不含结束，同一人不能同时承担两项；本例地点相同，无路程。","人员":"妈妈","任务":["接待上门维修14:00—15:00","线上家长会14:30—15:30"]},c('妈妈当前这两项安排是否冲突？',sched,[.98,.01,.01],'14:30至15:00同一人需同时承担两项，明确重叠。'))
