row('T0094',3,'同一位家长周六要参加小朋友活动并接待维修。维修已定10:00至11:00，活动通知只有日期，没有开始和结束时刻。地点同小区，无需交通时间。',c('当前能否判断两项有效安排冲突？',sched,[.08,.08,.84],'活动时段缺失且没有已确定重叠，只能信息不足。'))
row('T0094',4,'今天姥姥负责09:00至10:00买菜。日历仍有旧预约09:30至10:30口腔复查，但最新确认已取消，改为明天下午。今天没有其它任务，路程不计。',c('只比较今天仍有效的任务，是否有冲突？',sched,[.02,.965,.015],'复查已取消并移至明天，今天只剩买菜。'))
row('T0094',5,'同一人10:00至10:30线上会议，10:30至11:00在原地辅导作业。规则采用含开始不含结束的区间，任务切换无需时间。',s('评价两项有效任务直接时间重叠的长度。',overlap,[.98,.015,.005],'前项结束等于后项开始，没有共同占用时段。'))
row('T0094',6,'小周承担17:00至17:40取件，另有17:25至18:00陪同活动，两项均有效。只数直接时间交集，不加入路程。',s('评价两项有效任务的直接重叠程度。',overlap,[.02,.95,.03],'交集17:25至17:40为15分钟，属于中间等级上界。'))
row('T0094',7,'姑姑须13:00至14:30照看幼儿，另一预约要求13:30至14:15全程到场。没有替班人，两项均有效，直接比较时间。',s('评价两项任务直接重叠程度。',overlap,[.005,.015,.98],'交集13:30至14:15共45分钟，超过15。'))
row('T0094',8,'爸爸的家长会18:00至19:00，接站18:40至19:10，同一天且都必须本人在场，没有取消或代办记录。',n('爸爸的这两项有效安排是否存在直接时间重叠？',.98,'18:40至19:00为明确同人时间交集。'))
row('T0094',9,'妈妈10:00至11:00参加社区活动，爸爸10:15至11:15上门收快递。两人独立安排，均在同一住宅区，不共用车辆，也没有需要对方在场的条件。',n('这两项安排是否让同一个人在同一时间承担两项任务？',.01,'承接人不同且无共享资源限制，不能仅据时间重叠判同人冲突。'))
row('T0094',10,{"人员":"阿姨","周六安排":["14:00—15:00社区登记","15:20—16:00图书馆还书"],"交通规则":"第一项结束后才能出发，两地点间需20分钟；边界允许准时到达","天气":"当日是否下雨没有预报或实测"},c('按已有确定路程判断这两项安排。',sched,[.02,.96,.02],'15:00结束加20分钟路程恰到15:20，可以衔接。'),s('不含路程，评价两项任务的直接时间交集。',overlap,[.97,.02,.01],'两项任务时段分离，直接重叠为零。'),n('周六当天社区所在地是否会下雨？',.5,'没有天气依据，日程与确定路程不能推出降雨事实。'))

# T0095 收纳目录为本家庭规则，不依赖常识猜分类。
storage={"儿童柜":"无危险且仅供儿童使用的日常用品","高处工具箱":"尖锐工具；此项优先于用途分类","干燥电子柜":"非尖锐的带电电子配件","普通杂物格":"非尖锐、非电子且非儿童专用品","无法确定":"缺少确定收纳类别所必需的物品属性"}
fit=["拟放区域满足三条要求中的零或一条","拟放区域满足三条要求中的恰好两条","拟放区域同时满足三条要求"]
row('T0095',1,{"物品":"成人拆快递用尖头剪刀，不带电","家庭目录":"尖锐工具优先放高处工具箱；其次非尖锐电子配件放干燥电子柜；其余儿童专用放儿童柜，否则杂物格。"},c('按目录应放哪一区域？',storage,[.005,.97,.005,.01,.01],'剪刀明确尖锐，按优先规则进入高处工具箱。'))
row('T0095',2,'目录规则：尖锐优先工具箱；非尖锐电子配件入电子柜；再按儿童专用或普通杂物区分。物品为儿童学习机充电器，不尖锐，带电电子配件。',c('依目录优先级，应归放何处？',storage,[.025,.005,.95,.01,.01],'虽然给儿童学习机用，电子配件规则优先于儿童专用。'))
row('T0095',3,'待收纳物装在不透明袋里，标签只写“小东西”。没有打开检查，不知道是否尖锐、电子配件或儿童专用。目录按这些属性决定位置。',c('当前能够确定哪个收纳区域？',storage,[.025,.025,.025,.045,.88],'用于分类的必要物品属性全部缺少，不能按袋子大小猜。'))
row('T0095',4,'家庭规则：尖锐工具优先工具箱，非尖锐电子配件其次电子柜，之后儿童专用入儿童柜，其余杂物格。物品是成人围棋棋子，无尖角，不带电。旧袋上“儿童玩具”是借用包装，已确认物品并非儿童专用。',c({'依据':'使用已确认的当前物品属性','排除':'不要把旧包装字样视为实际用途'},storage,[.015,.005,.005,.96,.015],'成人棋子不尖锐非电子且非儿童专用，应进普通杂物格。'))
row('T0095',5,'相机配件存放要求：干燥、遮光、离地三条都满足。拟放在阳台地面透明箱；记录显示该处潮湿、受直射阳光、箱底贴地。',s('只评价拟放区域满足三条要求的数量。',fit,[.98,.015,.005],'三条均明确失败，属于零或一条档。'))
row('T0095',6,'药用量杯的家庭存放规则需干燥、独立分格、有名称标签。抽屉确认干燥且已独立分格，但仍没有名称标签；不评价其它用药事项。',s('评价拟放区域对这三条收纳要求的满足程度。',fit,[.02,.96,.02],'干燥和分格两条满足，标签一条未满足。'))
row('T0095',7,'针线盒必须有盖、儿童够不到、内设分隔。候选高柜顶部盒子已盖紧，儿童无法触及，并有针线分隔槽，记录已逐项核对。',s('评价该位置满足给定三条收纳要求的程度。',fit,[.005,.015,.98],'三条均有直接核对记录，全部满足。'))
row('T0095',8,'家庭明确规定所有备用纽扣电池都放上锁高柜，儿童柜不收。新收纳的是备用纽扣电池，已核验标签。',n('按这份目录，这盒电池是否应归上锁高柜？',.98,'目录直接点名该物品必须放上锁高柜。'))
row('T0095',9,'家庭收纳规则规定剪刀进入高处工具箱，禁止放儿童柜。待收纳剪刀明确有尖端，成人使用，未加安全套。',n('按给定规则，这把剪刀是否可以放儿童柜？',.01,'规则直接禁止剪刀放儿童柜，物品确是剪刀。'))
row('T0095',10,{"物品":"儿童专用软布玩偶，非电子，无尖锐部件","目录":"尖锐优先工具箱，非尖锐电子进电子柜，其余儿童专用品入儿童柜，否则杂物格。","儿童柜要求":"干燥、有独立格、有名称标签","已查":"柜体干燥，有独立格，名称标签尚未贴","未查":"家中是否还留着同款玩偶未盘点"},c('该物品按目录应归哪一区域？',storage,[.965,.005,.005,.015,.01],'非尖锐非电子且儿童专用，对应儿童柜。'),s('评价已查儿童柜满足三条收纳要求的数量。',fit,[.02,.96,.02],'干燥与独立格成立，标签未贴，恰好两条。'),n('家中是否还存在另一只同款玩偶？',.5,'未盘点同款物品，当前一只的属性不能证明有无另一只。'))
